import json, os, sys
import market_model

def items(x):
    if isinstance(x, list):
        return x
    if isinstance(x, dict):
        for k in ('items', 'listings', 'catalog', 'rows', 'deals'):
            if isinstance(x.get(k), list):
                return x[k]
        return list(x.values())
    return []

def text(x):
    return json.dumps(x, ensure_ascii=False, default=str).lower()

def skus(x):
    out = set()
    if isinstance(x, dict):
        for k, v in x.items():
            if k.lower() == 'sku' and isinstance(v, (str, int)):
                out.add(str(v).lower())
            else:
                out.update(skus(v))
    elif isinstance(x, list):
        for v in x:
            out.update(skus(v))
    return out

a = json.load(sys.stdin)
md = os.environ['MARKET_DIR']
with open(os.path.join(md, 'catalog.json'), encoding='utf-8') as f:
    catalog = items(json.load(f))
rows = list(market_model.load_rows(md))
terms = [str(a.get(k, '')).strip().lower() for k in ('query', 'category') if str(a.get(k, '')).strip()]
limit = max(1, min(100, int(a.get('limit', 20))))
cat = [r for r in catalog if not terms or any(t in text(r) for t in terms)]
matched_skus = skus(cat)
ledger = [r for r in rows if (not terms or any(t in text(r) for t in terms) or bool(skus(r) & matched_skus))]
print(json.dumps({'catalog': cat[:limit], 'ledger': ledger[-limit:]}, ensure_ascii=False, default=str))
